using DriveOS.Modules.Workforce.Domain.PerformanceReviews; using DriveOS.SharedKernel.Identifiers;
namespace DriveOS.UnitTests.Modules.Workforce.PerformanceReviews;
public sealed class PerformanceReviewTests{[Fact]public void Submit_requires_all_criteria_rated_and_summary(){var r=PerformanceReview.Create(PerformanceReviewId.New(),OrganizationId.New(),EmployeeId.New(),UserId.New(),new DateOnly(2026,1,1),new DateOnly(2026,6,30),"Mid-year",DateTimeOffset.UtcNow,UserId.New()).Value;r.AddCriterion(PerformanceReviewCriterionId.New(),"QUALITY","Quality",100,null,DateTimeOffset.UtcNow,UserId.New());Assert.True(r.Submit(DateTimeOffset.UtcNow,UserId.New()).IsFailure);}[Fact]public void Completed_review_is_immutable(){var actor=UserId.New();var r=PerformanceReview.Create(PerformanceReviewId.New(),OrganizationId.New(),EmployeeId.New(),actor,new DateOnly(2026,1,1),new DateOnly(2026,6,30),"Mid-year",DateTimeOffset.UtcNow,actor).Value;var c=PerformanceReviewCriterionId.New();r.AddCriterion(c,"QUALITY","Quality",100,null,DateTimeOffset.UtcNow,actor);r.RateCriterion(c,5,null,DateTimeOffset.UtcNow,actor);r.SetSummary("Excellent",null,DateTimeOffset.UtcNow,actor);r.Submit(DateTimeOffset.UtcNow,actor);r.Acknowledge(null,DateTimeOffset.UtcNow,actor);r.Complete(DateTimeOffset.UtcNow,actor);Assert.True(r.SetSummary("Changed",null,DateTimeOffset.UtcNow,actor).IsFailure);}}
